using namespace std;

int characterCount;
int bestAnswer;
vector<vector<int>> clauses;
vector<vector<int>> clausesByCharacter;
vector<char> covered;

bool isSubset(const vector<int>& a, const vector<int>& b) {
    for (int x : a) {
        if (!binary_search(b.begin(), b.end(), x)) return false;
    }
    return true;
}

void searchAnswer(int selectedCount) {
    if (selectedCount >= bestAnswer) return;

    int uncoveredCount = 0;
    vector<int> frequency(characterCount, 0);

    for (int i = 0; i < (int)clauses.size(); ++i) {
        if (covered[i]) continue;
        ++uncoveredCount;
        for (int c : clauses[i]) ++frequency[c];
    }

    if (uncoveredCount == 0) {
        bestAnswer = selectedCount;
        return;
    }

    int maxCoverage = *max_element(frequency.begin(), frequency.end());
    int lowerBound = (uncoveredCount + maxCoverage - 1) / maxCoverage;

    vector<char> used(characterCount, false);
    int disjointBound = 0;
    for (int i = 0; i < (int)clauses.size(); ++i) {
        if (covered[i]) continue;

        bool disjoint = true;
        for (int c : clauses[i]) {
            if (used[c]) {
                disjoint = false;
                break;
            }
        }

        if (disjoint) {
            ++disjointBound;
            for (int c : clauses[i]) used[c] = true;
        }
    }

    lowerBound = max(lowerBound, disjointBound);
    if (selectedCount + lowerBound >= bestAnswer) return;

    int chosenClause = -1;
    int chosenSize = 1000;
    int chosenScore = 0;

    for (int i = 0; i < (int)clauses.size(); ++i) {
        if (covered[i]) continue;

        int score = 0;
        for (int c : clauses[i]) score += frequency[c];

        if ((int)clauses[i].size() < chosenSize ||
            ((int)clauses[i].size() == chosenSize && score < chosenScore)) {
            chosenClause = i;
            chosenSize = clauses[i].size();
            chosenScore = score;
        }
    }

    vector<int> candidates = clauses[chosenClause];
    sort(candidates.begin(), candidates.end(), [&](int a, int b) {
        return frequency[a] > frequency[b];
    });

    for (int c : candidates) {
        vector<int> changed;
        for (int clauseIndex : clausesByCharacter[c]) {
            if (!covered[clauseIndex]) {
                covered[clauseIndex] = true;
                changed.push_back(clauseIndex);
            }
        }

        searchAnswer(selectedCount + 1);

        for (int clauseIndex : changed) covered[clauseIndex] = false;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    set<string> uniqueStrings;
    set<unsigned char> uniqueCharacters;

    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        uniqueStrings.insert(s);
        for (unsigned char c : s) uniqueCharacters.insert(c);
    }

    vector<string> strings(uniqueStrings.begin(), uniqueStrings.end());
    if (strings.size() <= 1) {
        cout << 0;
        return 0;
    }

    vector<unsigned char> characters(uniqueCharacters.begin(), uniqueCharacters.end());
    characterCount = characters.size();

    array<int, 256> characterIndex;
    characterIndex.fill(-1);
    for (int i = 0; i < characterCount; ++i) {
        characterIndex[characters[i]] = i;
    }

    vector<vector<char>> present(strings.size(), vector<char>(characterCount, false));
    for (int i = 0; i < (int)strings.size(); ++i) {
        for (unsigned char c : strings[i]) {
            present[i][characterIndex[c]] = true;
        }
    }

    vector<vector<int>> allClauses;
    bool impossible = false;

    for (int i = 0; i < (int)strings.size(); ++i) {
        for (int j = i + 1; j < (int)strings.size(); ++j) {
            vector<int> clause;
            for (int c = 0; c < characterCount; ++c) {
                if (present[i][c] != present[j][c]) clause.push_back(c);
            }

            if (clause.empty()) {
                impossible = true;
            } else {
                allClauses.push_back(move(clause));
            }
        }
    }

    if (impossible) {
        cout << characterCount;
        return 0;
    }

    sort(allClauses.begin(), allClauses.end(), [](const auto& a, const auto& b) {
        if (a.size() != b.size()) return a.size() < b.size();
        return a < b;
    });
    allClauses.erase(unique(allClauses.begin(), allClauses.end()), allClauses.end());

    for (const auto& clause : allClauses) {
        bool redundant = false;
        for (const auto& kept : clauses) {
            if (kept.size() > clause.size()) break;
            if (isSubset(kept, clause)) {
                redundant = true;
                break;
            }
        }
        if (!redundant) clauses.push_back(clause);
    }

    clausesByCharacter.assign(characterCount, {});
    for (int i = 0; i < (int)clauses.size(); ++i) {
        for (int c : clauses[i]) clausesByCharacter[c].push_back(i);
    }

    bestAnswer = characterCount;

    vector<char> greedyCovered(clauses.size(), false);
    int greedyCount = 0;
    int remaining = clauses.size();

    while (remaining > 0) {
        int bestCharacter = -1;
        int bestCoverage = -1;

        for (int c = 0; c < characterCount; ++c) {
            int count = 0;
            for (int idx : clausesByCharacter[c]) {
                if (!greedyCovered[idx]) ++count;
            }
            if (count > bestCoverage) {
                bestCoverage = count;
                bestCharacter = c;
            }
        }

        ++greedyCount;
        for (int idx : clausesByCharacter[bestCharacter]) {
            if (!greedyCovered[idx]) {
                greedyCovered[idx] = true;
                --remaining;
            }
        }
    }

    bestAnswer = greedyCount;
    covered.assign(clauses.size(), false);
    searchAnswer(0);

    cout << bestAnswer;
    return 0;
}

