using Mask = uint64_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<string> input(n);
    for (string& s : input) cin >> s;

    sort(input.begin(), input.end());
    input.erase(unique(input.begin(), input.end()), input.end());

    if (input.size() <= 1) {
        cout << 0;
        return 0;
    }

    vector<char> chars;
    for (const string& s : input)
        for (char c : s)
            chars.push_back(c);

    sort(chars.begin(), chars.end());
    chars.erase(unique(chars.begin(), chars.end()), chars.end());

    const int k = static_cast<int>(chars.size());

    vector<Mask> signatures;
    signatures.reserve(input.size());

    for (const string& s : input) {
        Mask signature = 0;
        for (char c : s) {
            int index = lower_bound(chars.begin(), chars.end(), c) - chars.begin();
            signature |= Mask(1) << index;
        }
        signatures.push_back(signature);
    }

    vector<Mask> constraints;
    for (int i = 0; i < static_cast<int>(signatures.size()); ++i) {
        for (int j = i + 1; j < static_cast<int>(signatures.size()); ++j) {
            Mask difference = signatures[i] ^ signatures[j];
            if (difference == 0) {
                cout << k;
                return 0;
            }
            constraints.push_back(difference);
        }
    }

    sort(constraints.begin(), constraints.end());
    constraints.erase(unique(constraints.begin(), constraints.end()),
                      constraints.end());

    sort(constraints.begin(), constraints.end(), [](Mask a, Mask b) {
        int pa = __builtin_popcountll(a);
        int pb = __builtin_popcountll(b);
        return pa != pb ? pa < pb : a < b;
    });

    vector<Mask> reduced;
    for (Mask mask : constraints) {
        bool redundant = false;
        for (Mask other : reduced) {
            if ((other & mask) == other) {
                redundant = true;
                break;
            }
        }
        if (!redundant) reduced.push_back(mask);
    }
    constraints.swap(reduced);

    Mask greedy = 0;
    while (true) {
        bool complete = true;
        vector<int> coverage(k, 0);

        for (Mask constraint : constraints) {
            if ((constraint & greedy) != 0) continue;
            complete = false;

            Mask bits = constraint;
            while (bits) {
                int bit = __builtin_ctzll(bits);
                ++coverage[bit];
                bits &= bits - 1;
            }
        }

        if (complete) break;

        int bestBit = max_element(coverage.begin(), coverage.end()) -
                      coverage.begin();
        greedy |= Mask(1) << bestBit;
    }

    int answer = __builtin_popcountll(greedy);
    unordered_set<Mask> visited;

    auto search = [&](auto&& self, Mask selected) -> void {
        int selectedCount = __builtin_popcountll(selected);
        if (selectedCount >= answer) return;
        if (!visited.insert(selected).second) return;

        Mask disjointUnion = 0;
        int lowerBound = 0;
        for (Mask constraint : constraints) {
            if ((constraint & selected) == 0 &&
                (constraint & disjointUnion) == 0) {
                disjointUnion |= constraint;
                ++lowerBound;
            }
        }

        if (selectedCount + lowerBound >= answer) return;

        Mask branchConstraint = 0;
        for (Mask constraint : constraints) {
            if ((constraint & selected) == 0) {
                branchConstraint = constraint;
                break;
            }
        }

        if (branchConstraint == 0) {
            answer = selectedCount;
            return;
        }

        vector<pair<int, int>> candidates;
        Mask bits = branchConstraint;

        while (bits) {
            int bit = __builtin_ctzll(bits);
            Mask bitMask = Mask(1) << bit;
            int coverage = 0;

            for (Mask constraint : constraints) {
                if ((constraint & selected) == 0 &&
                    (constraint & bitMask) != 0) {
                    ++coverage;
                }
            }

            candidates.emplace_back(-coverage, bit);
            bits &= bits - 1;
        }

        sort(candidates.begin(), candidates.end());

        for (auto [ignored, bit] : candidates)
            self(self, selected | (Mask(1) << bit));
    };

    search(search, 0);

    cout << answer;
    return 0;
}

